n = int(input())
counts = {"ERROR": 0, "WARN": 0, "INFO": 0}
errors = []

for _ in range(n):
    time, level, message = input().split(maxsplit=2)
    counts[level] += 1
    if level == "ERROR":
        errors.append(f"- {time} {message}")

for level, count in counts.items():
    print(f"{level}: {count}")
for line in errors:
    print(line)
